namespace ReelDiscovery.Tests.Evidence.Golden;

// Frozen before the Phase 6 change: Base64 (UTF-8, LF line endings) of the Phase 5 ComposeFragment / ComposeHtml
// output for ComposeHtmlGoldenFixtures.All(); Base64 so git line-ending conversion cannot alter it.
// Html constants have the disclaimer PNG masked (ComposeHtmlGoldenFixtures.MaskBanner). Do not regenerate.
internal static class ComposeHtmlGolden
{
    public const string PlainFragment = "";
    public const string PlainHtml = "";
    public const string QuotedReplyFragment = "";
    public const string QuotedReplyHtml = "";
    public const string ForwardFragment = "";
    public const string ForwardHtml = "";
    public const string PrivilegedFragment = "";
    public const string PrivilegedHtml = "";
    public const string TableFragment = "";
    public const string TableHtml = "";

    public static string Fragment(string name) => Get(name + "Fragment");

    public static string Html(string name) => Get(name + "Html");

    private static string Get(string field)
    {
        var value = (string)typeof(ComposeHtmlGolden).GetField(field)!.GetValue(null)!;
        return System.Text.Encoding.UTF8.GetString(Convert.FromBase64String(value));
    }
}
